1691→          console.log(chalk.gray(`  ${step.message}`));
1692→        }
1693→      }
1694→    }
1695→
1696→    const success = steps.every((s) => s.status !== "failed");
1697→
1698→    return {
1699→      success,
1700→      steps,
1701→      coreSkillsInstalled,
1702→      skillsRendered,
1703→      hooksInstalled,
1704→      agentsMdGenerated,
1705→      permissionsSeeded,
1706→      memorySeeded,
1707→    };
1708→  } catch (err) {
1709→    debugLog("runSetupPipeline failed", err);
1710→    return {
1711→      success: false,
1712→      steps,
1713→      coreSkillsInstalled,
1714→      skillsRendered,
1715→      hooksInstalled,
1716→      agentsMdGenerated,
1717→      permissionsSeeded,
1718→      memorySeeded,
1719→    };
1720→  }
1721→}
