1723→/**
1724→ * Register the 'setup' command
1725→ * AC: @enhanced-setup ac-1 through ac-9
1726→ */
1727→export function registerSetupCommand(program: Command): void {
1728→  program
1729→    .command("setup")
1730→    .description("Configure agent environment for kspec (orchestrated pipeline)")
1731→    .option(
1732→      "--agent <type>",
1733→      "Explicit agent type override (claude-code|cline|cursor|windsurf|unknown)",
1734→    )
1735→    .option("--dry-run", "Show what would be done without making changes")
1736→    .option(
1737→      "--author <author>",
1738→      "Custom author string (default: auto-detected based on agent)",
1739→    )
1740→    .option("--no-hooks", "Skip installing hooks")
1741→    .option("--skip-skills", "Skip rendering skills")
1742→    .option("--status", "Report current setup state without making changes")
1743→    .option("--force", "Overwrite existing configuration")
1744→    .option(
1745→      "--auto-worktree",
1746→      "Automatically create .kspec worktree if kspec-meta branch exists",
1747→    )
1748→    .action(async (options) => {
1749→      try {
1750→        const projectDir = process.cwd();
1751→        const agentOverride = options.agent
1752→          ? parseSetupAgentOverride(options.agent)
1753→          : undefined;
1754→
1755→        // AC: @enhanced-setup ac-7, ac-8 - --status mode
1756→        if (options.status) {
1757→          const status = await getSetupStatus(projectDir, agentOverride);
1758→
1759→          output(status, () => {
1760→            console.log(chalk.bold("kspec Setup Status\n"));
1761→
1762→            // Agent detection
1763→            console.log(chalk.gray("Agent:"));
1764→            console.log(
1765→              `  Detected: ${status.agent.detected} (${status.agent.confidence} confidence)`,
1766→            );
1767→            console.log();
1768→
1769→            // Hooks status
1770→            console.log(chalk.gray("Hooks:"));
1771→            console.log(
1772→              `  UserPromptSubmit: ${status.hooks.promptCheck ? chalk.green("✓") : chalk.red("✗")}`,
1773→            );
1774→            console.log(
1775→              `  Stop:             ${status.hooks.stop ? chalk.green("✓") : chalk.red("✗")}`,
1776→            );
1777→            console.log(
1778→              `  PreToolUse:       ${status.hooks.preToolUse ? chalk.green("✓") : chalk.red("✗")}`,
1779→            );
1780→            if (status.hooks.guardsPresent.length > 0) {
1781→              console.log(
1782→                `  Guards:           ${status.hooks.guardsPresent.join(", ")}`,
1783→              );
1784→            }
1785→            console.log();
1786→
1787→            // Skills status
1788→            console.log(chalk.gray("Skills:"));
1789→            console.log(`  Rendered: ${status.skills.rendered}`);
1790→            if (status.skills.drifted > 0) {
1791→              console.log(
1792→                `  Drifted:  ${chalk.yellow(status.skills.drifted.toString())}`,
1793→              );
1794→            }
1795→            console.log();
1796→
1797→            // Plugin marketplace status
1798→            // AC: @enhanced-setup ac-7, ac-8
1799→            console.log(chalk.gray("Plugin:"));
1800→            console.log(
1801→              `  Marketplace: ${status.plugin.marketplaceRegistered ? (status.plugin.marketplaceHealthy ? chalk.green("healthy") : chalk.yellow("registered")) : chalk.red("not registered")}`,
1802→            );
1803→            console.log(
1804→              `  Enabled:     ${status.plugin.pluginEnabled ? chalk.green("✓") : chalk.red("✗")}`,
1805→            );
1806→            if (status.plugin.registeredPath) {
1807→              console.log(chalk.gray(`  Path: ${status.plugin.registeredPath}`));
1808→            }
1809→            if (status.plugin.healthMessage && !status.plugin.marketplaceHealthy) {
1810→              console.log(chalk.yellow(`  ${status.plugin.healthMessage}`));
1811→            }
1812→            console.log();
1813→
1814→            // Agents.md status
1815→            console.log(chalk.gray("kspec-agents.md:"));
1816→            if (status.agentsMd.exists) {
1817→              // AC: @doctor-command ac-staleness-unknown — show appropriate color for unknown status
1818→              const statusColor =
1819→                status.agentsMd.status === "current"
1820→                  ? chalk.green
1821→                  : status.agentsMd.status === "unknown"
1822→                    ? chalk.yellow
1823→                    : chalk.yellow;
1824→              console.log(`  Status: ${statusColor(status.agentsMd.status)}`);
1825→              if (status.agentsMd.status === "unknown") {
1826→                console.log(chalk.gray("  Could not determine staleness (no manifest or hash unavailable)"));
1827→              }
1828→              if (status.agentsMd.generatedAt) {
1829→                console.log(`  Generated: ${status.agentsMd.generatedAt}`);
1830→              }
1831→            } else {
1832→              console.log(`  Status: ${chalk.red("missing")}`);
1833→              console.log(
1834→                chalk.gray("  Run 'kspec setup' to generate"),
1835→              );
1836→            }
1837→            console.log();
1838→
1839→            // Seeding status
1840→            console.log(chalk.gray("Seeding:"));
1841→            console.log(
1842→              `  Permissions: ${status.seeding.permissionsSeeded ? chalk.green("✓") : chalk.gray("○")}`,
1843→            );
1844→            console.log(
1845→              `  Memory:      ${status.seeding.memorySeeded ? chalk.green("✓") : chalk.gray("○")}`,
1846→            );
1847→            if (status.seeding.memoryPath) {
1848→              console.log(
1849→                chalk.gray(`  Path: ${status.seeding.memoryPath}`),
1850→              );
1851→            }
1852→          });
1853→          return;
1854→        }
1855→
1856→        // AC: detect-existing-repo, auto-worktree-flag, worktree-already-exists
1857→        const worktreeReady = await ensureWorktree(
1858→          options.autoWorktree || false,
1859→        );
1860→        if (!worktreeReady) {
1861→          // User declined worktree creation or it failed
1862→          process.exit(EXIT_CODES.ERROR);
1863→        }
1864→
1865→        const detected = agentOverride
1866→          ? buildDetectedAgent(agentOverride)
1867→          : detectAgent();
1868→        const dryRun = options.dryRun || false;
1869→
1870→        if (detected.type === "unknown") {
1871→          warn("Could not auto-detect agent environment");
1872→          printManualInstructions("unknown");
1873→          return;
1874→        }
1875→
1876→        // AC: @setup-pipeline-unification ac-3 - delegate to runSetupPipeline()
1877→        // One code path for both 'kspec setup' and 'kspec init --setup'
1878→        const result = await runSetupPipeline(projectDir, {
1879→          dryRun,
1880→          skipSkills: options.skipSkills || false,
1881→          installHooks: options.hooks !== false,
1882→          force: options.force || false,
1883→          agent: agentOverride,
1884→          author: options.author,
1885→          configureAuthor: true,
1886→        });
1887→
1888→        // AC: @enhanced-setup ac-1 - Display summary
1889→        // AC: @enhanced-setup ac-6 - dry-run displays planned actions
1890→        output(
1891→          {
1892→            dry_run: dryRun,
1893→            steps: result.steps.map((s) => ({
1894→              name: s.name,
1895→              status: s.status,
1896→              message: s.message,
1897→              details: s.details,
1898→            })),
1899→          },
1900→          () => {
1901→            if (dryRun) {
1902→              console.log(chalk.yellow("DRY RUN - No changes made\n"));
1903→            }
1904→
1905→            // Pipeline already prints the summary when not dry-run
1906→            // For dry-run, print it here since the pipeline skips output
1907→            if (dryRun) {
1908→              console.log(chalk.bold("kspec Setup Summary\n"));
1909→
1910→              for (const step of result.steps) {
1911→                const icon =
1912→                  step.status === "done"
1913→                    ? chalk.green("✓")
1914→                    : step.status === "skipped"
1915→                      ? chalk.gray("○")
1916→                      : chalk.red("✗");
1917→                const statusText =
1918→                  step.status === "done"
1919→                    ? ""
1920→                    : step.status === "skipped"
1921→                      ? chalk.gray(" (skipped)")
1922→                      : chalk.red(" (failed)");
1923→
1924→                console.log(`${icon} ${step.name}${statusText}`);
1925→                if (step.message) {
1926→                  console.log(chalk.gray(`  ${step.message}`));
1927→                }
1928→              }
1929→            }
1930→
1931→            console.log();
1932→
1933→            if (dryRun) {
1934→              console.log(
1935→                chalk.yellow("Run without --dry-run to apply changes."),
1936→              );
1937→            } else {
1938→              console.log(
1939→                chalk.green("Setup complete."),
1940→              );
1941→              console.log(
1942→                chalk.gray("Restart your agent session for changes to take effect."),
1943→              );
1944→            }
1945→          },
1946→        );
1947→      } catch (err) {
1948→        error(errors.failures.setupFailed, err);
1949→        process.exit(EXIT_CODES.ERROR);
1950→      }
1951→    });
1952→}
